<?php get_header(); the_post(); $id = get_the_ID(); $p = function_exists('estate_property_data') ? estate_property_data($id) : null; $agent_id = absint(get_post_meta($id, 'agent', true)); $gallery = (array) get_post_gallery_images($id); ?>
<div class="wrap"><div class="page-intro"><a class="text-link" href="<?php echo esc_url(home_search_archive_url()); ?>">← Back to properties</a></div><div class="property-hero<?php echo $gallery ? '' : ' no-gallery'; ?>"><div><?php if (has_post_thumbnail()) : the_post_thumbnail('full', ['loading' => 'eager']); else : ?><div class="property-placeholder">Home Search</div><?php endif; ?></div><div class="property-hero-side"><?php foreach (array_slice($gallery, 0, 2) as $src) : ?><img src="<?php echo esc_url($src); ?>" alt="Additional view of <?php echo esc_attr(get_the_title()); ?>" loading="lazy"><?php endforeach; ?></div></div>
<div class="detail-layout"><div><div class="detail-title"><div><span class="eyebrow"><?php echo esc_html($p['type'] ?? 'Property'); ?></span><h1><?php the_title(); ?></h1><p class="muted"><?php echo esc_html(get_post_meta($id, 'address', true) ?: get_post_meta($id, 'location', true)); ?></p></div><div class="detail-price"><?php echo esc_html(home_search_money($p['price'] ?? 0)); ?></div></div><div class="detail-specs"><div><strong><?php echo esc_html($p['beds'] ?? 0); ?></strong><span>Bedrooms</span></div><div><strong><?php echo esc_html($p['baths'] ?? 0); ?></strong><span>Bathrooms</span></div><div><strong><?php echo esc_html($p['area'] ?? 0); ?></strong><span>Square meters</span></div></div><div class="detail-copy"><h2>About this home</h2><?php the_content(); ?></div><div class="calculator" data-price="<?php echo esc_attr($p['price'] ?? 0); ?>"><span class="eyebrow">Plan your move</span><h2>Monthly payment estimate</h2><p class="muted">An estimate for planning only. Your lender will confirm actual terms.</p><div class="calculator-grid"><div class="field"><label for="down-payment">Down payment (%)</label><input id="down-payment" type="number" min="0" max="99" value="20"></div><div class="field"><label for="interest-rate">Annual interest (%)</label><input id="interest-rate" type="number" min="0" max="100" step="0.1" value="7"></div><div class="field"><label for="loan-years">Loan term (years)</label><input id="loan-years" type="number" min="1" max="40" value="20"></div></div><p class="payment-result" role="status">Estimated monthly: <strong id="monthly-payment">—</strong></p></div></div>
<aside class="side-card"><span class="eyebrow">See it in person</span><h2>Schedule a viewing.</h2><?php if ($agent_id && get_post_status($agent_id) === 'publish') : ?><div class="agent-mini"><?php echo get_the_post_thumbnail($agent_id, 'thumbnail'); ?><div><strong><?php echo esc_html(get_the_title($agent_id)); ?></strong><span><?php echo esc_html(get_post_meta($agent_id, 'agent_role', true) ?: 'Property advisor'); ?></span></div></div><?php endif; ?><?php $viewing = sanitize_key(home_search_query_value('viewing')); if ($viewing === 'sent') : ?><p class="form-status" role="status">Your request was sent. The agent will be in touch.</p><?php elseif ($viewing) : ?><p class="form-status error" role="alert">Please check your details and try again.</p><?php endif; ?><?php if (!$agent_id || get_post_status($agent_id) !== 'publish' || !is_email(get_post_meta($agent_id, 'agent_email', true))) : ?><p class="notice">Viewing requests are unavailable for this property. Please contact the office.</p><a class="button" href="<?php echo esc_url(home_search_contact_url()); ?>">Contact us</a><?php else : ?><form action="<?php echo esc_url(admin_url('admin-post.php')); ?>" method="post"><input type="hidden" name="action" value="estate_viewing"><input type="hidden" name="property_id" value="<?php echo esc_attr($id); ?>"><?php wp_nonce_field('estate_viewing_' . $id, 'estate_nonce'); ?><div class="field"><label for="view-name">Your name</label><input id="view-name" name="name" required autocomplete="name"></div><div class="field"><label for="view-email">Email address</label><input id="view-email" name="email" type="email" required autocomplete="email"></div><div class="field"><label for="view-phone">Phone (optional)</label><input id="view-phone" name="phone" type="tel" autocomplete="tel"></div><div class="field"><label for="view-message">Message (optional)</label><textarea id="view-message" name="message" placeholder="Tell us when you'd like to visit"></textarea></div><div class="field" style="position:absolute;left:-9999px" aria-hidden="true"><label for="view-website">Website</label><input id="view-website" name="website" tabindex="-1" autocomplete="off"></div><button class="button button-accent" type="submit">Request a viewing ↗</button></form><?php endif; ?></aside></div></div>
<?php get_footer(); ?>
